//! 🧪️ Completed canonical receiving proves exact handle/mesh transfer and physical custody against Serde.
use super::*;
use semio_os_flow_host_session::{FlowPreviewMesh,preview_receiving::*};
use semio_framework::MeshData;
use semio_framework_value::{RetirementDemand, ValueRefusalKind};
use semio_framework_value::retained_clone::RetainedCloneGrant;
use semio_framework_value::retirement::controlled::ControlledRetirement;
use semio_framework_value::{DslValue, Number};
use semio_framework_job::{OperationId,Generation};
use semio_framework_value::ToValue;
fn observe<T>(action:impl FnOnce()->T)->(T,(usize,usize)){let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(action);(result,(heap.requested_bytes,heap.released_bytes))}
fn dto(value:&serde_json::Value)->DslValue{match value{serde_json::Value::Null=>DslValue::Null,serde_json::Value::Bool(value)=>DslValue::Bool(*value),serde_json::Value::Number(value)=>DslValue::Number(value.as_u64().map(Number::UInt).unwrap_or_else(||Number::Float(value.as_f64().unwrap()))),serde_json::Value::String(value)=>DslValue::String(value.clone()),serde_json::Value::Array(value)=>DslValue::Array(value.iter().map(dto).collect()),serde_json::Value::Object(value)=>DslValue::Object(value.iter().map(|(key,value)|(key.clone(),dto(value))).collect())}}
/// 🧮️ Normalizes the independent Serde oracle: keys are ordered by the map and every number is compared as its `f64` value, because the canonical mesh carries float channels the fixture writes as integers.
fn canonical(value:&serde_json::Value)->serde_json::Value{match value{serde_json::Value::Number(number)=>serde_json::json!(number.as_f64().unwrap()),serde_json::Value::Array(items)=>serde_json::Value::Array(items.iter().map(canonical).collect()),serde_json::Value::Object(rows)=>serde_json::Value::Object(rows.iter().map(|(key,value)|(key.clone(),canonical(value))).collect()),other=>other.clone()}}
fn wire_canonical(value:&DslValue)->serde_json::Value{canonical(&serde_json::from_str(&semio_framework_pack_json::to_json_string(value)).unwrap())}
fn fixture()->serde_json::Value{serde_json::from_str(read_node("📥️evaluation-source/🔎️read/📨️response/🧪️tests/🧫️fixtures/🔣️.json")).unwrap()}
fn preview_finite_caller()->semio_framework_job::OriginalJobFixtureCaller{let law:serde_json::Value=serde_json::from_str(read_node("📥️preview/🧪️tests/🧫️fixtures/🔁️replacement.json")).unwrap();let source=&law["caller"];assert_eq!(occupied_policy(&source["turn"]),PREVIEW_FIXED_TURN);semio_framework_job::OriginalJobFixtureCaller::admit(OperationId(source["operation"].as_u64().unwrap()),Generation(source["generation"].as_u64().unwrap()),occupied_policy(&source["stock"]),||Some(1000),source["deadline"].as_u64().unwrap(),source["fuel"].as_u64().unwrap())}
const PREVIEW_FIXED_TURN:RetainedCloneGrant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:1048576,maximum_release_bytes:268435456,maximum_depth:4096};
fn preview_finite_grant(body:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:body,..PREVIEW_FIXED_TURN}}
fn preview_close_grant(body:usize,quote:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:body.max(quote),..PREVIEW_FIXED_TURN}}
fn preview_finite_close(receiver:&mut FlowPreviewCompletedReceiver,session:&mut FlowEvalSession,issuer:&mut semio_framework_job::OriginalJobFixtureCaller,body:usize)->(usize,usize){let mut total=(0,0);receiver.begin_close();for turn in 0..65536{if receiver.terminal_is_empty(){break}let grant=preview_close_grant(body,receiver.next_close_demands(body).unwrap().copy_bytes);let(step,heap)=observe(||issuer.bare_turn(grant,|cx|receiver.close_step(cx)));step.unwrap();let progress=issuer.receipt();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));total.0+=heap.0;total.1+=heap.1;assert!(turn<65535)}assert!(receiver.terminal_is_empty());session.begin_close();for turn in 0..65536{if session.terminal_is_empty(){return total}let grant=preview_close_grant(body,session.next_close_copy_byte_demand().unwrap());let(step,heap)=observe(||issuer.bare_turn(grant,|cx|{let demand=RetirementDemand{copy_bytes:session.next_close_copy_byte_demand()?,capacity_bytes:session.next_close_capacity_byte_demand(body)?,release_bytes:session.next_close_release_byte_demand()?,depth:session.next_close_depth_demand()?};semio_framework_job::close_original_effect_step(cx,demand,|effect|semio_framework_value::RetainedWorkPoll::Complete(session.retire_source_step(effect)))}));step.unwrap();let progress=issuer.receipt();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));total.0+=heap.0;total.1+=heap.1;assert!(turn<65535)}unreachable!()}

#[test]
fn original_completed_preview_moves_mesh16_into_paid_cache_with_full_custody(){
 let mut fixture=fixture();fixture["nodeHash"]=serde_json::json!(u64::MAX);let oracle=canonical(&fixture["mesh"]);
 for body in [1,3,64]{let mut issuer=preview_finite_caller();let((value,mut session),heap)=observe(||(dto(&fixture),FlowEvalSession::new()));let mut sums=heap;let handle_pointer=object(&value).unwrap().iter().find(|(key,_)|key=="handle").map(|(_,value)|text(value).unwrap().as_ptr()).unwrap();let(mut receiver,heap)=observe(||issuer.turn(preview_finite_grant(body),|cx|Ok(FlowPreviewCompletedReceiver::new(value,cx).unwrap_or_else(|_|panic!("original receiver intake")))).unwrap());assert_eq!(heap,(0,0));let address=FlowPreviewCompletedAddress{window_id:fixture["windowId"].as_str().unwrap(),window_kind_id:fixture["windowKindId"].as_str().unwrap(),handle:fixture["handle"].as_str().unwrap(),node_hash:u64::MAX,tolerance:fixture["tolerance"].as_f64().unwrap()};let mut positions_pointer=None;
  for turn in 0..65536{if receiver.terminal_is_empty(){break}let d=session.next_preview_tessellate_demands(&receiver,body).unwrap();let g=preview_close_grant(body,d.copy_bytes);let before=(receiver.test_diagnostic(),session.preview_mesh_by_handle.len());for denied in [Some(RetainedCloneGrant{maximum_items:0,..g}),Some(RetainedCloneGrant{maximum_depth:0,..g}),(d.capacity_bytes>0).then(||RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes-1,..g}),(d.release_bytes>0).then(||RetainedCloneGrant{maximum_release_bytes:d.release_bytes-1,..g}),(d.copy_bytes>0&&session.next_preview_tessellate_demands(&receiver,d.copy_bytes-1).unwrap().copy_bytes>d.copy_bytes-1).then(||RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes-1,..g})].into_iter().flatten(){let fuel=issuer.fuel_remaining();let ledger=issuer.cumulative_receipt();let(result,heap)=observe(||issuer.turn(denied,|cx|session.resolve_preview_tessellate(&mut receiver,&address,cx)));assert!(!result.unwrap());assert_eq!(heap,(0,0));assert_eq!(issuer.cumulative_receipt(),ledger);assert_eq!(issuer.fuel_remaining(),fuel);assert_eq!((receiver.test_diagnostic(),session.preview_mesh_by_handle.len()),before)}for(fuel,deadline)in[(0,1500),(1,1000)]{let original=issuer.fuel_remaining();let ledger=issuer.cumulative_receipt();let(result,heap)=observe(||issuer.turn(g,|cx|cx.with_original_work_loan(fuel,deadline,|same|session.resolve_preview_tessellate(&mut receiver,&address,same))));assert!(!result.unwrap());assert_eq!(heap,(0,0));assert_eq!(issuer.cumulative_receipt(),ledger);assert_eq!(issuer.fuel_remaining(),original)}let(result,heap)=observe(||issuer.turn(g,|cx|session.resolve_preview_tessellate(&mut receiver,&address,cx)));let progress=issuer.receipt();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));sums.0+=heap.0;sums.1+=heap.1;result.unwrap();if let Some(pointer)=receiver.test_diagnostic().incoming_positions{positions_pointer=Some(pointer)}assert!(turn<65535)}
  {assert!(receiver.terminal_is_empty()&&receiver.test_diagnostic().committed);let(handle,entry)=session.preview_mesh_by_handle.iter().next().unwrap();let mesh=&entry.mesh;assert_eq!(handle.as_ptr(),handle_pointer);assert_eq!(Some(mesh.positions.as_ptr()as usize),positions_pointer);assert_eq!(wire_canonical(&mesh.to_value()),oracle)}issuer.cancel().cancel_now();let returned=preview_finite_close(&mut receiver,&mut session,&mut issuer,body);sums.0+=returned.0;sums.1+=returned.1;assert_eq!(sums.0,sums.1);assert_eq!(observe(||drop(receiver)).1,(0,0));assert_eq!(observe(||drop(session)).1,(0,0));let stock=issuer.stock();issuer.retire(stock);
 }
}
#[test]
fn original_completed_preview_refuses_late_cancel_and_business_mismatch_before_cache_commit(){
 for mismatch in [false,true]{let fixture=fixture();let mut issuer=preview_finite_caller();let((value,mut session),heap)=observe(||(dto(&fixture),FlowEvalSession::new()));let mut sums=heap;let mut receiver=issuer.turn(preview_finite_grant(64),|cx|Ok(FlowPreviewCompletedReceiver::new(value,cx).unwrap_or_else(|_|panic!("original receiver intake")))).unwrap();let address=FlowPreviewCompletedAddress{window_id:fixture["windowId"].as_str().unwrap(),window_kind_id:fixture["windowKindId"].as_str().unwrap(),handle:fixture["handle"].as_str().unwrap(),node_hash:if mismatch{0}else{fixture["nodeHash"].as_u64().unwrap()},tolerance:fixture["tolerance"].as_f64().unwrap()};let mut failure=None;
  for turn in 0..65536{if !mismatch&&receiver.test_diagnostic().phase==9{issuer.cancel().cancel_now()}let fuel=issuer.fuel_remaining();let funded=preview_close_grant(64,session.next_preview_tessellate_demands(&receiver,64).unwrap().copy_bytes);let(result,heap)=observe(||issuer.turn(funded,|cx|session.resolve_preview_tessellate(&mut receiver,&address,cx)));let progress=issuer.receipt();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));sums.0+=heap.0;sums.1+=heap.1;if let Err(original)=result{assert_eq!(original.primary_value().unwrap().kind,ValueRefusalKind::InvalidValue);assert!(original.receipt_refusal.is_none());assert_eq!(issuer.fuel_remaining(),fuel-1);failure=Some(original);break}if issuer.cancel().is_cancelled_now(){assert_eq!(heap,(0,0));assert_eq!(progress,Default::default());break}assert!(turn<65535)}assert_eq!(failure.is_some(),mismatch);assert!(session.preview_mesh_by_handle.is_empty());issuer.cancel().cancel_now();let mut closing=ControlledRetirement::new(failure).unwrap_or_else(|_|panic!("original native refusal close"));for turn in 0..65536{if closing.terminal_is_empty(){break}let grant=preview_close_grant(3,closing.selected_demand(3).unwrap().copy_bytes);let(result,heap)=observe(||issuer.turn(grant,|cx|semio_framework_job::close_original_effect_step(cx,closing.selected_demand(3)?,|effect|closing.step(effect.grant().maximum_copy_bytes,effect))));result.unwrap();let progress=issuer.receipt();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));sums.0+=heap.0;sums.1+=heap.1;assert!(turn<65535)}assert!(closing.terminal_is_empty());assert_eq!(observe(||drop(closing)).1,(0,0));let returned=preview_finite_close(&mut receiver,&mut session,&mut issuer,3);sums.0+=returned.0;sums.1+=returned.1;assert_eq!(sums.0,sums.1);assert_eq!(observe(||drop(receiver)).1,(0,0));assert_eq!(observe(||drop(session)).1,(0,0));let stock=issuer.stock();issuer.retire(stock);
 }
}

fn occupied_policy(value:&serde_json::Value)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:value["maximumItems"].as_u64().unwrap()as usize,maximum_copy_bytes:value["maximumCopyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:value["maximumCapacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:value["maximumReleaseBytes"].as_u64().unwrap()as usize,maximum_depth:value["maximumDepth"].as_u64().unwrap()as usize}}
#[test]
fn original_completed_preview_replaces_same_handle_without_copying_or_losing_original_mesh(){
 use semio_framework_job::OriginalJobFixtureCaller;
 let law:serde_json::Value=serde_json::from_str(read_node("📥️preview/🧪️tests/🧫️fixtures/🔁️replacement.json")).unwrap();let source=&law["caller"];let stock=occupied_policy(&source["stock"]);let grant=occupied_policy(&source["turn"]);let mut issuer=OriginalJobFixtureCaller::admit(OperationId(source["operation"].as_u64().unwrap()),Generation(source["generation"].as_u64().unwrap()),stock,||Some(1000),source["deadline"].as_u64().unwrap(),source["fuel"].as_u64().unwrap());let fixture=fixture();let(mut session,heap)=observe(FlowEvalSession::new);let mut sums=heap;
 let mut previous=None;
 let tolerances=law["toleranceRounds"].as_array().unwrap();assert_eq!(tolerances.len() as u64,law["rounds"].as_u64().unwrap());
 for (round,tolerance) in tolerances.iter().enumerate(){
  let mut fixture=fixture.clone();fixture["tolerance"]=tolerance.clone();
  let handle=fixture["handle"].as_str().unwrap();let tolerance=tolerance.as_f64().unwrap();
  let address=FlowPreviewCompletedAddress{window_id:fixture["windowId"].as_str().unwrap(),window_kind_id:fixture["windowKindId"].as_str().unwrap(),handle,node_hash:fixture["nodeHash"].as_u64().unwrap(),tolerance};
  assert!(session.preview_mesh_for_tolerance(handle,tolerance).is_none());
  assert_eq!(session.preview_mesh(handle).is_some(),round>0);
  let prior_epoch=session.preview_mesh_epoch();let(value,heap)=observe(||dto(&fixture));sums.0+=heap.0;sums.1+=heap.1;let handle_pointer=object(&value).unwrap().iter().find(|(key,_)|key=="handle").map(|(_,value)|text(value).unwrap().as_ptr()).unwrap();let(mut receiver,heap)=observe(||issuer.turn(grant,|cx|Ok(FlowPreviewCompletedReceiver::new(value,cx).unwrap_or_else(|_|panic!("original occupied intake")))).unwrap());assert_eq!(heap,(0,0));let mut incoming=None;let mut displaced=false;
  for turn in 0..65536{if receiver.terminal_is_empty(){break}let before=issuer.fuel_remaining();for(fuel,deadline)in[(0,1500),(1,1000)]{let ledger=issuer.cumulative_receipt();let(result,heap)=observe(||issuer.turn(grant,|cx|cx.with_original_work_loan(fuel,deadline,|same|session.resolve_preview_tessellate(&mut receiver,&address,same))));assert!(!result.unwrap());assert_eq!(heap,(0,0));assert_eq!(issuer.cumulative_receipt(),ledger);assert_eq!(issuer.fuel_remaining(),before)}let quote=session.next_preview_tessellate_demands(&receiver,grant.maximum_copy_bytes).unwrap().copy_bytes;let funded=RetainedCloneGrant{maximum_copy_bytes:grant.maximum_copy_bytes.max(quote),..grant};let(result,heap)=observe(||issuer.turn(funded,|cx|session.resolve_preview_tessellate(&mut receiver,&address,cx)));let progress=issuer.receipt();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));sums.0+=heap.0;sums.1+=heap.1;result.unwrap();if let Some(pointer)=receiver.test_diagnostic().incoming_positions{incoming=Some(pointer)}if let Some(pointers)=receiver.test_diagnostic().displaced{assert_eq!(Some(pointers),previous);displaced=true}assert!(turn<65535)}
  assert!(receiver.terminal_is_empty()&&receiver.test_diagnostic().received&&receiver.test_diagnostic().committed);assert_eq!(session.preview_mesh_by_handle.len(),law["expectedEntries"].as_u64().unwrap()as usize);let(handle,entry)=session.preview_mesh_by_handle.iter().next().unwrap();let mesh=&entry.mesh;assert_eq!(handle.as_ptr(),handle_pointer);assert_eq!(Some(mesh.positions.as_ptr()as usize),incoming);if round>0{assert!(displaced);assert_ne!(Some((handle.as_ptr()as usize,mesh.positions.as_ptr()as usize)),previous)}previous=Some((handle.as_ptr()as usize,mesh.positions.as_ptr()as usize));assert_eq!(wire_canonical(&mesh.to_value()),canonical(&fixture["mesh"]));assert!(std::ptr::eq(session.preview_mesh_for_tolerance(handle,tolerance).unwrap(),mesh));if round>0{assert!(session.preview_mesh_for_tolerance(handle,tolerances[round-1].as_f64().unwrap()).is_none());}let epoch=session.preview_mesh_epoch();assert!(epoch>prior_epoch);let slot=(0..session.preview_mesh_slot_count()).find(|slot|session.preview_mesh_at_slot(*slot,epoch).unwrap().is_some()).unwrap();let((same_handle,same_mesh),heap)=observe(||session.preview_mesh_at_slot(slot,epoch).unwrap().unwrap());assert_eq!(heap,(0,0));assert_eq!(same_handle.as_ptr(),handle_pointer);assert_eq!(Some(same_mesh.positions.as_ptr()as usize),incoming);let(refusal,heap)=observe(||session.preview_mesh_at_slot(slot,prior_epoch));assert!(refusal.is_err());assert_eq!(heap,(0,0));assert_eq!(observe(||drop(receiver)).1,(0,0));
 }
 issuer.cancel().cancel_now();session.begin_close();for turn in 0..65536{if session.terminal_is_empty(){break}let copy=3.max(session.next_close_copy_byte_demand().unwrap());let(result,heap)=observe(||issuer.bare_turn(RetainedCloneGrant{maximum_copy_bytes:copy,..grant},|cx|cx.with_original_retirement(|cx|{let demand=RetirementDemand{copy_bytes:session.next_close_copy_byte_demand()?,capacity_bytes:session.next_close_capacity_byte_demand(copy)?,release_bytes:session.next_close_release_byte_demand()?,depth:session.next_close_depth_demand()?};semio_framework_job::close_original_effect_step(cx,demand,|effect|semio_framework_value::RetainedWorkPoll::Complete(session.retire_source_step(effect)))})));result.unwrap();let progress=issuer.receipt();if turn<4||turn%20000==0{eprintln!("[DEBUG] preview session close turn={turn} p={progress:?} q={:?} fuel={}",(session.next_close_copy_byte_demand(),session.next_close_capacity_byte_demand(3),session.next_close_release_byte_demand(),session.next_close_depth_demand()),issuer.fuel_remaining());}assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));sums.0+=heap.0;sums.1+=heap.1;assert!(turn<65535)}assert!(session.terminal_is_empty());assert_eq!(observe(||drop(session)).1,(0,0));assert_eq!(sums.0,sums.1);issuer.retire(stock);
}

#[test]
fn original_preview_detail_admission_keeps_one_request_per_handle() {
 let law:serde_json::Value=serde_json::from_str(read_node("📥️preview/🧪️tests/🧫️fixtures/🔁️replacement.json")).unwrap();
 for row in law["admission"].as_array().unwrap() {
  let mut session=FlowEvalSession::new();
  let handle="same-shape";
  if let Some(tolerance)=row["resident"].as_f64() {
   session.preview_mesh_by_handle.insert(handle.into(),FlowPreviewMesh{tolerance,mesh:MeshData::default()});
  }
  if row["inFlight"].as_bool().unwrap() {
   assert!(session.note_pending_tessellate(6,handle.into(),0.05));
  }
  let requested=row["requested"].as_f64().unwrap();
  assert_eq!(session.note_pending_tessellate(7,handle.into(),requested),row["admitted"].as_bool().unwrap());
  assert_eq!(session.preview_mesh(handle).is_some(),!row["resident"].is_null());
  session.retire_cold();
 }
}

/// 📈️ Original owner phases remain cancellable and preserve the actual bilingual progress vocabulary.
#[test]
fn original_completed_preview_progress_phases_preserve_actual_geometry_admission(){
 let schema:serde_json::Value=serde_json::from_str(read_node("../🧩️extensions/🕸️wasm/🧬️schema/📐️tessellation/📈️progress/🔣️.json")).unwrap();
 for tag in schema["properties"]["phase"]["enum"].as_array().unwrap(){let tag=tag.as_str().unwrap();let phase=PreviewTessellatePhase::from_tag(tag);assert_eq!(phase.tag(),tag);assert!(phase.is_cancellable());let(en,de)=phase.labels();assert!(!en.is_empty()&&!de.is_empty());assert_ne!(en,de);}
}
